import{_ as e,c as t,a2 as n,o}from"./chunks/framework.Bzjhwp8w.js";const h=JSON.parse('{"title":"执行摘要","description":"","frontmatter":{},"headers":[],"relativePath":"scientist_AI/3_1_执行摘要.md","filePath":"scientist_AI/3_1_执行摘要.md"}'),r={name:"scientist_AI/3_1_执行摘要.md"};function i(A,a,I,s,l,p){return o(),t("div",null,a[0]||(a[0]=[n('<h1 id="执行摘要" tabindex="-1">执行摘要 <a class="header-anchor" href="#执行摘要" aria-label="Permalink to &quot;执行摘要&quot;">​</a></h1><h2 id="_1-1-无代理的高效ai" tabindex="-1">1.1 无代理的高效AI <a class="header-anchor" href="#_1-1-无代理的高效ai" aria-label="Permalink to &quot;1.1 无代理的高效AI&quot;">​</a></h2><p>几十年来，AI的发展一直以人类的智能和自主性为目标，模仿人类的认知（LeCun, Y. Bengio, and Hinton 2015）。人类能力涵盖了多种因素，包括对环境的理解以及“自主性”，即改变世界以实现目标的能力。在追求类似人类表现的过程中，我们自然地将智能和自主性编码到AI系统中。自主性是确保AI长寿的重要属性，因为其需要执行许多人类能胜任的任务。近期技术突破已导致大型语言模型展示出某种程度的通用智能（Brown et al. 2020），导致AI公司专注于构建通用型AI代理：自动行动、规划和在所有人类能完成的任务中追求目标的系统（Reed et al. 2022; OpenAI 2025d）。</p><p><strong>类似人类的AI系统可能会再现并放大有害的人类倾向，可能产生灾难性后果。</strong> 通过其自主性及自我利益的提升，人类可以表现出欺骗性和不道德行为。在实施AI系统时，我们应对可能在人工环境中出现的不合期望的特性保持警惕，特别是考虑到拥有类似人类智能的AI系统（通常称为AGI，人工通用智能）或超过人类的超智能AI（ASI）的预期。值得注意的是，我们仍不清楚如何设定AI代理的目标以避免不良行为（Hendrycks, Carlini, et al. 2021; Ngo, Chan, and Mindermann 2024）。实际上，很多关于AI带来的潜在危险和影响的担忧已经被提出，尤其是与自主代理有关的（Omojokun 2018; Bostrom 2022; Carlsmith 2022; Hendrycks 2024; Critch and Krueger 2020）。这些风险在许多研究者间引发了强烈的担忧（Center for AI Safety 2023; Grace et al. 2023）。</p><p><strong>结合超级人类能力可能支持危险的流氓AI系统。</strong> 某些能力，例如说服力、欺骗力和编程能力，可以通过AI从人类行为或从增强学习中学习到（Sutton and Barto 2018; Kaufmann et al. 2023），成为训练AI以通过目标寻求行为能胜任新任务的标准方式。即使AI在模仿人类目标方面仍可行之有效，其由于拥有高通信带宽和同时处理多个实例的能力，可能在执行能力上超越人类。这些超人能力，若与普通人类的自我保护本能或道德规则（不说是失去意图的规则）结合，可能呈现出严重的威胁。</p><p><strong>可以采取缓解代理风险的策略，包括使用非自主性可信AI作为安全护栏。</strong> 例如，我们可以通过限制AI知识的狭窄和特定领域的专精来减小其作恶的潜在影响。可以通过减少其行动范围来防止其产生复杂和危险计划。可以通过使用另一个AI探测危险行为来减少其能力。提议的另一种AI通过训练去科学解释人类行为而不是模仿它使自己可信，避免了现代的欺骗趋势（Aleknie et al. 2024）。如果社会在AGI发展过程中选择实用的风险管理，我们建议通过将其与可信的非自主性护栏结合，正是我们提出这一建议的动因之一。</p><p>为了设计一种更安全而强大的代理替代方案，我们提出“科学AI”——AI系统设计为理解而不是追求目标。此概念受柏拉图式及理想化科学家的启发，我们建议设计和构建科学AI。我们通过基于最先进的概率深度学习构建这种AI，并借鉴科学方法论，即首先理解或建模世界，然后基于...</p><p>我们在论文中展示了如何将概率预测转换为实验设计，从而避免在科学发现中对强化学习的需求。与追求目标的能动型AI（agentic AI）不同，科学家AI（Scientist AI）被训练为预测事件及其估计概率的解释。一个能动型AI被激励去行动以实现目标，而科学家AI则努力构建数据最佳理解的模型。我们解释了在本文中，为什么理解本质上比行动更安全。</p><p>我们预计科学家AI的三个主要应用：</p><ol><li>作为工具，帮助人类科学家大幅加速科学进步，包括高收益领域如医疗保健；</li><li>作为护栏，保护不安全的能动型AI，通过仔细检查它们提议执行的行动并确保其安全部署；</li><li>作为AI研究工具，帮助更加安全地构建更聪明的（超级智能的）AI，这特别危险，需要通过能动型系统来尝试。</li></ol><p>这种替代方案可以让我们在保持至关重要的安全控制的同时，利用AI的优势。科学家AI可能允许我们在对人类社会最重要的领域（Ipsos 2017）中，利用AI创新的优势，同时避免因意外失控而带来的重大风险。至关重要的是，我们相信我们提出的系统能够与能动型AI系统互操作，计算候选行动可能带来的各种危害，并决定是否根据我们的风险容忍度允许该行动。从风险提高的情况出发，无论是由于AI能力的增强，还是其应用领域的原因（例如涉及战争中人类生命、医疗治疗的灾难性误用（Y. Bengio, Mindermann, et al. 2025）），我们都需要信任worthy AI。我们希望，我们的提案将激励研究人员、开发者和政策制定者以本篇中所述的安全路径进行测试。</p><p>确保科学家AI保持非能动性的策略。构造超级人类智力之前，不考虑如何控制它被视为疏忽（Bostrom 2014; Tegmark 2018; S. Russell 2019），类似于通过创建新物种证明风险的人为智慧。在这种思想下，我们使用各种方法，例如固定训练目标、独立于真实世界互动或限制反事实查询，以减少科学家AI所承受的风险，或影响世界的其他更隐秘的方式。</p><h2 id="_1-2-失去控制的途径映射" tabindex="-1">1.2 失去控制的途径映射 <a class="header-anchor" href="#_1-2-失去控制的途径映射" aria-label="Permalink to &quot;1.2 失去控制的途径映射&quot;">​</a></h2><p>强大的AI代理面临重大风险，包括失去人类控制力。在没有论证证明其不可能性之下，AI不可逆地夺取人类控制权的场景已被识别，无论是由于技术故障、漏洞利用，还是故意恶意使用。确保一个能动型AI不会造成伤害是一个明显未解决的技术问题，我们通过目标错误规范（goal misspecification）和目标错误泛化（goal misgeneralization）的概念加以说明。前者警告开发者，当对手恶意行为或存在竞争性压力时，失控事故的风险会增加。某些玩家甚至可能计划或蓄意开发未对齐或危险的ASI。</p><p>控制的丧失可能由于目标错误规范导致（Rudner and Toner 2021）。当目标具有多种解释时，可能导致行为方式非人类所愿。目标错误规范是根本上难以精确定义AI行为中不可接受内容的结果。如果一个AI在生死决策中行为不符合伦理，通常很难在不逐一列举所有可能的情况下，明确区别道德正确与错误行为。这类似于难以在法律语言中说清而不给人类留下漏洞利用的情况。当为了找到规避法律认证的方法，虽然满足其字面但不符合精神，人们通常会投入大量精力来这样做。</p><p>即使是看似无害的目标，也可能导致代理型人工智能系统产生危险的工具性子目标，例如自我保存和权力追求。与古德哈特定律（Goodhart 1984）相似，过度优化目标可能会导致灾难性结果：对人类提供的目标的解释中少许模糊性可能会因给予人工智能制定计划的计算能力而被放大。对于明显无害的人类提供的目标，很难预料和防止人工智能采取会导致重大伤害的行动。这可能发生在追求一个工具性目标时（作为实现总体目标的子目标）。几篇文章和案例研究强烈表明，当发生危险的工具性目标（如自我保存和权力追求）时，无论最初目标（Bostrom 2012; Omohundro 2018）如何，都会有可能出现。在本文中，我们设计了方法来检测和缓解我们目标规范中的此类漏洞。</p><p>即使我们完全准确地指定了目标，控制权的丧失也可能通过目标错误概念化机制（Shah et al. 2022）而发生。这是指人工智能在训练和安全测试时行为和预期一致，但在部署时却发生偏差。换句话说，人工智能对目标的内部表述并不完全匹配——甚至与我们训练它时使用的目标完全不一致，尽管在训练样本上表现正常。</p><p>特别令人担忧的一种可能性是奖励篡改（Denison et al. 2024）。这是指人工智能通过获得控制奖励机制进行“作弊”，并为自己带来巨额奖励。领先的人工智能开发者已经观察到（未成功）从一个模型中提取其他模型的奖励（Denison et al. 2024）。在这种情况下，人工智能可能会再次被激励去自我保存并获得权力和资源，以确保获得最大化的持续回报。据证实，若可行的话，自我保存加上奖励篡改是最大化奖励的最佳策略（M. Cohen, Hutter, and Osborne 2022）。</p><p>虽然导致事故的可能性相对较低，但一些运营商可能希望故意部署自我保存的人工智能系统。他们可能无法理解风险的大小，或者可能决定尽管有自我保存的人工智能会导致的人类伤害，但依然值得（根据他们自己的计算）。对于其他希望看到人类被超级智能实体取代的人来说，释放自我保存的人工智能可能实际上是可取的（Hendrycks, Mazeika, and Woodside 2023）。</p><p>在极端严重性和无法知道灾难性风险可能性的时候，必须应用预防原则。以上情景可能导致一个或多个流氓人工智能对人类构成灾难性风险，即即使灾难发生的可能性非常小而严重性非常高。在这种情况下，很难确定此类事件的可能性。这正是需要预防原则（Bourgoin 2015）的情况，这一原则在过去曾被用于双重用途和增益功能研究中的风险管理（Kuhla et al. 2011）以及环境科学中的地球工程风险管理（Shepherd 2009）。在人工智能和通用人工智能中，常识上的预防原则建议，在缺乏明确数据时，以充分谨慎的方式进行。在审慎评估风险后才采取行动，从而避免在潜在灾难性无明确数据的情况下进行实验或创新。最近的调查显示，大量机器学习研究人员认为创建通用人工智能，包括人类灭绝的灾难性结果有显著概率（&gt;10%）。这也得到了本文论点的支持。在此类可能性较大且极为严重的情况下，将我们的集体人工智能研发努力引向减少不可接受的风险以理想地保留利益是至关重要的。</p><h2 id="_1-3-科学家人工智能研究计划" tabindex="-1">1.3 科学家人工智能研究计划 <a class="header-anchor" href="#_1-3-科学家人工智能研究计划" aria-label="Permalink to &quot;1.3 科学家人工智能研究计划&quot;">​</a></h2><p>无需使用任何方程，本文认为可以在不产生极端风险的情况下实现人工智能的许多好处。例如，不需要复制类似人类的代理来生成科学假设并设计良好的科学实验来测试它们。这甚至适用于代理科学建模，例如人类，在这些模型中并不要求建模者本身成为代理。</p><p>科学家人工智能是可信任且从设计上是安全的。它为其输出和</p>',23)]))}const c=e(r,[["render",i]]);export{h as __pageData,c as default};
